@startuml

class GasStation {
  + Id : int
  + Address : string
}

class FuelPump {
  + PumpNumber : int
  + SelfService : boolean
}

class Fuel {
  + Name : string
  + Octane : int
}

class DailyPrice {
  + Date : date
  + PricePerLiter : double
}

class FuelPurchase {
  + Id : int
  + LitersDispensed : int
}

GasStation "1" *-- "1..12" FuelPump
GasStation "1" -- "*" DailyPrice
FuelPump "*" -- "*" Fuel
DailyPrice "*" -- "1" Fuel
FuelPurchase "*" -- "1" FuelPump
FuelPurchase "*" -- "1" DailyPrice

@enduml

